void r2_rng_get(long out[32], int *front, int *rear)
{
    int i;
    for (i = 0; i < 32; ++i) out[i] = rntb[i];
    *front = (int)(fptr - rntb);
    *rear = (int)(rptr - rntb);
}

int r2_rng_set(const long in[32], int front, int rear)
{
    int i;
    if (front < 1 || front > 31 || rear < 1 || rear > 31) return 0;
    for (i = 0; i < 32; ++i) rntb[i] = in[i];
    state = &rntb[1];
    fptr = &rntb[front];
    rptr = &rntb[rear];
    end_ptr = &rntb[32];
    return 1;
}

